) VALUES (
    'lake-louise-venue-guide',
    '{"en": "Lake Louise: Speed Skiing in the Canadian Rockies", "de": "Lake Louise: Speed-Skiing in den kanadischen Rocky Mountains", "fr": "Lake Louise : Le ski de vitesse dans les Rocheuses canadiennes", "it": "Lake Louise: Sci veloce nelle Montagne Rocciose canadesi", "es": "Lake Louise: Esquí de velocidad en las Montañas Rocosas canadienses", "pt": "Lake Louise: Esqui de velocidade nas Montanhas Rochosas canadenses", "nl": "Lake Louise: Snelheidsskiën in de Canadese Rocky Mountains", "ar": "ليك لويز: تزلج السرعة في جبال روكي الكندية", "ja": "レイク・ルイーズ：カナディアンロッキーでのスピードスキー", "zh": "Lake Louise: Jianada Luoji Shanmai de Sudu Huaxue", "ko": "레이크 루이스: 캐나다 로키산맥에서의 스피드 스키"}'::jsonb,
    '{"en": "The World Cup season traditionally kicks off at Lake Louise with speed events set against the stunning backdrop of the Canadian Rockies. A bucket-list destination for skiing fans.", "de": "Die Weltcup-Saison beginnt traditionell in Lake Louise mit Speed-Events vor der atemberaubenden Kulisse der kanadischen Rocky Mountains.", "fr": "La saison de Coupe du monde débute traditionnellement à Lake Louise avec des épreuves de vitesse sur fond des Rocheuses canadiennes.", "it": "La stagione di Coppa del Mondo inizia tradizionalmente a Lake Louise con gare di velocità sullo sfondo delle Montagne Rocciose canadesi.", "es": "La temporada de la Copa del Mundo tradicionalmente comienza en Lake Louise con eventos de velocidad con el impresionante telón de fondo de las Montañas Rocosas canadienses.", "pt": "A temporada da Copa do Mundo tradicionalmente começa em Lake Louise com eventos de velocidade contra o cenário impressionante das Montanhas Rochosas canadenses.", "nl": "Het Wereldbekerseizoen begint traditioneel in Lake Louise met snelheidsevenementen tegen de prachtige achtergrond van de Canadese Rocky Mountains.", "ar": "تبدأ موسم كأس العالم تقليدياً في ليك لويز مع سباقات السرعة على خلفية جبال روكي الكندية المذهلة", "ja": "ワールドカップシーズンは伝統的に、カナディアンロッキーの素晴らしい背景を持つレイク・ルイーズでのスピードイベントで始まります。", "zh": "Shijie Bei saiji chuantong shang yi Lake Louise de sudu xiangmu kaishi, beijing shi lingren jingtan de Jianada Luoji Shanmai.", "ko": "월드컵 시즌은 전통적으로 캐나다 로키산맥의 멋진 배경을 가진 레이크 루이스에서 스피드 이벤트로 시작됩니다."}'::jsonb,
    '{"en": "<p>Lake Louise holds a special place in the World Cup <a href=\"/alpine-skiing-guide/\">alpine skiing</a> calendar as the traditional season opener for speed events. Located in Banff National Park, this Canadian venue offers a unique combination of challenging racing and spectacular natural beauty.</p><h2>Season Opener</h2><p>For decades, Lake Louise has kicked off the World Cup speed season. Athletes travel from Europe to the Canadian Rockies for the first major downhill and super-G races of the winter, making it a much-anticipated destination each year.</p><p>The early-season timing means snow conditions can vary, but organizers consistently deliver quality racing surfaces.</p><h2>The Course</h2><p>The downhill course descends through the stunning mountain terrain of Banff National Park. Wide-open sections allow for incredible speeds, while technical passages test athletes'' precision.</p><p>Champions like <a href=\"/sofia-goggia-profile/\">Sofia Goggia</a>, <a href=\"/mikaela-shiffrin-profile/\">Mikaela Shiffrin</a>, and <a href=\"/cornelia-huetter-profile/\">Cornelia Hütter</a> have conquered this North American classic.</p><h2>The Setting</h2><p>The turquoise waters of Lake Louise, set against snow-capped peaks, create one of the most photographed scenes in all of skiing. The natural beauty alone makes attending races here a memorable experience.</p><h2>Wildlife</h2><p>Racing in a national park means wildlife sightings are possible. Athletes and spectators occasionally spot bears, elk, and other Rocky Mountain wildlife - adding to the venue''s unique character.</p><h2>North American Skiing</h2><p>Lake Louise represents the best of North American ski racing. Canadian and American fans turn out to support their athletes and enjoy the start of the World Cup season.</p><h2>Getting There</h2><p>The venue is about 180 km west of Calgary International Airport. The drive through the Rocky Mountains is spectacular and part of the Lake Louise experience.</p>", "de": "<p>Lake Louise nimmt einen besonderen Platz im Weltcup-<a href=\"/alpine-skiing-guide/\">Ski Alpin</a>-Kalender ein als traditioneller Saisonauftakt für Speed-Events. Im Banff Nationalpark gelegen, bietet dieser kanadische Austragungsort eine einzigartige Kombination aus anspruchsvollem Racing und spektakulärer Naturschönheit.</p><h2>Saisonauftakt</h2><p>Seit Jahrzehnten eröffnet Lake Louise die Weltcup-Speed-Saison.</p><h2>Die Strecke</h2><p>Champions wie <a href=\"/sofia-goggia-profile/\">Sofia Goggia</a> und <a href=\"/mikaela-shiffrin-profile/\">Mikaela Shiffrin</a> haben diesen nordamerikanischen Klassiker bezwungen.</p><h2>Die Kulisse</h2><p>Die türkisfarbenen Wasser des Lake Louise vor schneebedeckten Gipfeln schaffen eine der meist fotografierten Szenen im gesamten Skisport.</p>", "fr": "<p>Lake Louise occupe une place spéciale dans le calendrier de la Coupe du monde de <a href=\"/alpine-skiing-guide/\">ski alpin</a> en tant qu''ouverture traditionnelle de la saison de vitesse. Situé dans le parc national de Banff, ce site canadien offre une combinaison unique de courses exigeantes et de beauté naturelle spectaculaire.</p><h2>Ouverture de saison</h2><p>Depuis des décennies, Lake Louise ouvre la saison de vitesse de la Coupe du monde.</p><h2>Le parcours</h2><p>Des champions comme <a href=\"/sofia-goggia-profile/\">Sofia Goggia</a> et <a href=\"/mikaela-shiffrin-profile/\">Mikaela Shiffrin</a> ont conquis ce classique nord-américain.</p>", "it": "<p>Lake Louise occupa un posto speciale nel calendario di Coppa del Mondo di <a href=\"/alpine-skiing-guide/\">sci alpino</a> come tradizionale apertura della stagione delle gare di velocità. Situato nel Parco Nazionale di Banff, questo sito canadese offre una combinazione unica di gare impegnative e spettacolare bellezza naturale.</p><h2>Apertura di stagione</h2><p>Da decenni, Lake Louise apre la stagione di velocità della Coppa del Mondo.</p><h2>Il percorso</h2><p>Campioni come <a href=\"/sofia-goggia-profile/\">Sofia Goggia</a> hanno conquistato questo classico nordamericano.</p>", "es": "<p>Lake Louise ocupa un lugar especial en el calendario de la Copa del Mundo de <a href=\"/alpine-skiing-guide/\">esquí alpino</a> como la apertura tradicional de la temporada de velocidad. Ubicado en el Parque Nacional de Banff, este lugar canadiense ofrece una combinación única de carreras desafiantes y belleza natural espectacular.</p><h2>Apertura de temporada</h2><p>Durante décadas, Lake Louise ha iniciado la temporada de velocidad de la Copa del Mundo.</p>", "pt": "<p>Lake Louise ocupa um lugar especial no calendário da Copa do Mundo de <a href=\"/alpine-skiing-guide/\">esqui alpino</a> como a abertura tradicional da temporada de velocidade. Localizado no Parque Nacional de Banff, este local canadense oferece uma combinação única de corridas desafiadoras e beleza natural espetacular.</p><h2>Abertura de temporada</h2><p>Por décadas, Lake Louise iniciou a temporada de velocidade da Copa do Mundo.</p>", "nl": "<p>Lake Louise heeft een speciale plaats in de Wereldbeker <a href=\"/alpine-skiing-guide/\">alpine skiën</a> kalender als de traditionele seizoensopener voor snelheidsevenementen. Gelegen in Banff National Park, biedt deze Canadese locatie een unieke combinatie van uitdagende races en spectaculaire natuurlijke schoonheid.</p><h2>Seizoensopener</h2><p>Al tientallen jaren opent Lake Louise het Wereldbeker snelheidsseizoen.</p>", "ar": "<p>يحتل ليك لويز مكانة خاصة في تقويم كأس العالم <a href=\"/alpine-skiing-guide/\">للتزلج الألبي</a> كافتتاح تقليدي لموسم السرعة. يقع في منتزه بانف الوطني، ويقدم هذا الموقع الكندي مزيجاً فريداً من السباقات الصعبة والجمال الطبيعي المذهل.</p><h2>افتتاح الموسم</h2><p>منذ عقود، افتتح ليك لويز موسم سرعة كأس العالم.</p>", "ja": "<p>レイク・ルイーズは、スピードイベントの伝統的なシーズンオープナーとして、ワールドカップ<a href=\"/alpine-skiing-guide/\">アルペンスキー</a>カレンダーで特別な位置を占めています。バンフ国立公園に位置するこのカナダの会場は、チャレンジングなレースと壮大な自然美のユニークな組み合わせを提供します。</p><h2>シーズンオープナー</h2><p>何十年もの間、レイク・ルイーズはワールドカップスピードシーズンを開始してきました。</p>", "zh": "<p>Lake Louise zai Shijie Bei <a href=\"/alpine-skiing-guide/\">gaoshan huaxue</a> rilicheng zhong zhanju tebie weizhi, zuowei sudu xiangmu de chuantong kaimu saishi. Weiyue Banff Guojia Gongyuan, zhe ge Jianada changguan tigong le tiaozhanxing bisai he zhuangguang ziran meili de dute jiehe.</p><h2>Saiji kaimu</h2><p>Ji shi nian lai, Lake Louise yizhi kaishi Shijie Bei sudu saiji.</p>", "ko": "<p>레이크 루이스는 스피드 이벤트의 전통적인 시즌 오프너로서 월드컵 <a href=\"/alpine-skiing-guide/\">알파인 스키</a> 캘린더에서 특별한 위치를 차지합니다. 밴프 국립공원에 위치한 이 캐나다 경기장은 도전적인 레이싱과 장엄한 자연미의 독특한 조합을 제공합니다.</p><h2>시즌 오프너</h2><p>수십 년 동안 레이크 루이스는 월드컵 스피드 시즌을 시작해 왔습니다.</p>"}'::jsonb,
    'venue-guide',
    'AS',
    '{"en": "Lake Louise venue guide - Canadian Rockies speed skiing venue in Banff National Park, traditional World Cup season opener with stunning mountain scenery.", "de": "Lake Louise Venue Guide - Speed-Skiing-Austragungsort in den kanadischen Rocky Mountains im Banff Nationalpark.", "fr": "Guide du site de Lake Louise - Site de ski de vitesse des Rocheuses canadiennes dans le parc national de Banff.", "it": "Guida alla sede di Lake Louise - Sede di sci veloce nelle Montagne Rocciose canadesi nel Parco Nazionale di Banff.", "es": "Guía del lugar de Lake Louise - Lugar de esquí de velocidad en las Rocosas canadienses en el Parque Nacional de Banff.", "pt": "Guia do local de Lake Louise - Local de esqui de velocidade nas Rochosas canadenses no Parque Nacional de Banff.", "nl": "Lake Louise locatiegids - Snelheidsskiën locatie in de Canadese Rocky Mountains in Banff National Park.", "ar": "دليل موقع ليك لويز - موقع تزلج السرعة في جبال روكي الكندية في منتزه بانف الوطني", "ja": "レイク・ルイーズ会場ガイド - バンフ国立公園のカナディアンロッキーのスピードスキー会場", "zh": "Lake Louise changguan zhinan - Banff Guojia Gongyuan Jianada Luoji Shanmai de sudu huaxue changguan", "ko": "레이크 루이스 경기장 가이드 - 밴프 국립공원 캐나다 로키산맥의 스피드 스키 경기장"}'::jsonb,
    'published',
    NOW(),
    'evergreen'
